<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import Button from 'primevue/button'; import Select from 'primevue/select'; import InputText from 'primevue/inputtext'; import InputNumber from 'primevue/inputnumber'; import Textarea from 'primevue/textarea'; import Dialog from 'primevue/dialog'; import ToggleSwitch from 'primevue/toggleswitch'; import { useToast } from 'primevue/usetoast';
import { api, currentUser } from '../lib/api'; import { useQuery } from '../composables/useQuery'; import { money, date, serviceNames, type Point, type Data, type Ride } from '../lib/types'; import OperationsMap from '../components/OperationsMap.vue'; import StatusBadge from '../components/StatusBadge.vue'; import QueryState from '../components/QueryState.vue'; import RideTable from '../components/RideTable.vue';
const toast = useToast(), isDriver = computed(() => currentUser.value?.role === 'Driver');
const places = ref<Data[]>([]), pickup = ref<Data>(), dropoff = ref<Data>(), service = ref('BIKE'), quote = ref<Data>(), quoteError = ref(''), busy = ref(false), pin = ref(''), collected = ref(0), cashReason = ref('FULL_AMOUNT_RECEIVED'), action = ref(''), reason = ref(''), supportVisible = ref(false), supportBody = ref(''), stars = ref(5), comment = ref(''), ratingVisible = ref(false), shareUrl = ref(''), demoMaps = ref(false), demoPosition = ref<Data>(), geoError = ref(''), geoPoint = ref<Point>(), now = ref(Date.now());
const active = useQuery(() => api<{ride: Ride | null}>('/rides/active'), 5000);
const history = useQuery(() => api<{items: Ride[]}>('/rides?pageSize=10'), 15000);
const availability = useQuery<Data>(() => isDriver.value ? api('/drivers/me/availability') : Promise.resolve({}), 5000);
const offers = useQuery<Data>(() => isDriver.value ? api('/drivers/me/offers/current') : Promise.resolve({}), 2000);
const earnings = useQuery<Data>(() => isDriver.value ? api('/drivers/me/earnings') : Promise.resolve({}), 15000);
const selectedRide = ref<Ride>();
const ride = computed(() => active.data.value?.ride ?? selectedRide.value); const offer = computed(() => offers.data.value?.offer);
const seconds = computed(() => quote.value ? Math.max(0, Math.floor((new Date(quote.value.expiresAt).getTime() - now.value) / 1000)) : 0);
const offerSeconds = computed(() => offer.value ? Math.max(0, Math.floor((new Date(offer.value.expiresAt).getTime() - now.value) / 1000)) : 0);
const mapPickup = computed(() => ride.value?.pickup ?? pickup.value as Point | undefined); const mapDropoff = computed(() => ride.value?.dropoff ?? dropoff.value as Point | undefined);
watch([pickup, dropoff, service], () => { quote.value = undefined; quoteError.value = ''; });
watch(() => ride.value?.payment?.id, () => { collected.value = ride.value?.payment ? ride.value.payment.payableAmount - ride.value.payment.paidAmount : 0; });
let clock: ReturnType<typeof setInterval> | undefined, heartbeat: ReturnType<typeof setInterval> | undefined, geoWatch: number | undefined;
async function run(work: () => Promise<void>) { busy.value = true; try { await work(); } catch (e) { toast.add({severity:'error',summary:(e as Error).message,life:6000}); } finally { busy.value = false; } }
async function reload() { await Promise.all([active.refresh(), history.refresh(), availability.refresh(), offers.refresh(), earnings.refresh()]); }
async function getQuote() { if (!pickup.value || !dropoff.value) return; quoteError.value = ''; await run(async () => { try { quote.value = await api('/quotes', {method:'POST',body:{pickup:pickup.value,dropoff:dropoff.value,serviceTypeCode:service.value,paymentMethodType:'CASH'}}); } catch(e) { quoteError.value = (e as Error).message; } }); }
async function book() { if (!quote.value) return; await run(async () => { await api('/rides',{method:'POST',idempotent:true,body:{quoteId:quote.value!.quoteId}}); quote.value = undefined; selectedRide.value = undefined; await reload(); }); }
async function location(): Promise<Data> {
  if (demoMaps.value && demoPosition.value) return {latitude:demoPosition.value.latitude,longitude:demoPosition.value.longitude,accuracyMeters:15,recordedAt:new Date().toISOString(),sequence:Date.now()};
  if (!navigator.geolocation) throw new Error('Thiết bị không hỗ trợ định vị.');
  return new Promise((resolve,reject) => navigator.geolocation.getCurrentPosition(pos => { const result = {latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracyMeters:pos.coords.accuracy,recordedAt:new Date(pos.timestamp).toISOString(),sequence:Date.now()}; geoPoint.value = {...result,address:'Vị trí thiết bị'}; resolve(result); }, () => reject(new Error('Không lấy được vị trí. Kiểm tra quyền GPS và thử lại.')), {enableHighAccuracy:true,timeout:12000,maximumAge:5000}));
}
async function publishLocation() { if (!isDriver.value || !availability.data.value?.online) return; try { const point = await location(); await api('/drivers/me/location-batches',{method:'POST',body:{samples:[point]}}); await api('/drivers/me/heartbeat',{method:'POST'}); geoError.value = ''; } catch(e) { geoError.value = (e as Error).message; } }
async function toggleOnline(value: boolean) { await run(async () => { await api('/drivers/me/availability',{method:'POST',body:{expectedVersion:availability.data.value?.version,online:value}}); await availability.refresh(); if(value) await publishLocation(); }); }
async function accept() { if(!offer.value) return; await run(async () => { await api('/driver-offers/'+offer.value!.offerId+'/accept',{method:'POST',idempotent:true,body:{expectedVersion:offer.value!.version}}); await reload(); }); }
async function reject() { if(!offer.value) return; await run(async () => { await api('/driver-offers/'+offer.value!.offerId+'/reject',{method:'POST'}); await offers.refresh(); }); }
async function command(kind: string) { if(!ride.value) return; await run(async () => { const body:Data = {expectedVersion:ride.value!.version}; if(kind==='start') body.pickupPin=pin.value; if(['arrive','complete'].includes(kind)) body.location=await location(); if(['cancel','release-assignment','no-show'].includes(kind)) body.reasonCode=reason.value; const result = await api<Ride>('/rides/'+ride.value!.rideId+'/'+kind,{method:'POST',idempotent:true,body}); action.value=''; pin.value=''; await reload(); if(result.status==='COMPLETED') { selectedRide.value=result; collected.value=result.payment?.payableAmount??0; } }); }
async function collect() { if(!ride.value?.payment) return; await run(async () => { await api('/payments/'+ride.value!.payment!.id+'/cash-collections',{method:'POST',idempotent:true,body:{operationId:'cash-'+ride.value!.payment!.id+'-'+ride.value!.payment!.paidAmount+'-'+collected.value,collectedAmount:collected.value,currency:'VND',reasonCode:cashReason.value}}); toast.add({severity:'success',summary:'Đã ghi nhận tiền mặt và bút toán',life:4000}); await reload(); }); }
async function share() { if(!ride.value)return; await run(async () => { const result = await api('/rides/'+ride.value!.rideId+'/share-tokens',{method:'POST'}); shareUrl.value=locationOrigin()+'/share/'+result.token; await navigator.clipboard?.writeText(shareUrl.value); toast.add({severity:'success',summary:'Đã tạo liên kết chia sẻ',detail:'Liên kết tự ngừng hiển thị khi chuyến kết thúc.',life:5000}); }); }
const locationOrigin = () => window.location.origin;
async function sos() { if(!ride.value)return; await run(async () => { const result = await api('/rides/'+ride.value!.rideId+'/safety-incidents',{method:'POST'}); toast.add({severity:'warn',summary:'Đã lưu cảnh báo nội bộ',detail:result.message,life:10000}); }); }
async function support() { await run(async () => { await api('/support/tickets',{method:'POST',body:{subject:'Hỗ trợ hành trình '+(ride.value?.rideCode??''),category:'RIDE',message:supportBody.value,rideId:ride.value?.rideId??null}}); supportVisible.value=false; supportBody.value=''; toast.add({severity:'success',summary:'Đã gửi yêu cầu hỗ trợ',life:4000}); }); }
async function rate() { if(!ride.value)return; await run(async () => { await api('/rides/'+ride.value!.rideId+'/ratings',{method:'POST',body:{stars:stars.value,comment:comment.value}}); ratingVisible.value=false; toast.add({severity:'success',summary:'Cảm ơn bạn đã chia sẻ trải nghiệm',life:3000}); }); }
onMounted(async () => { clock=setInterval(()=>{now.value=Date.now();},1000); window.addEventListener('grap:refresh',reload); try { const config=await api('/app-config');demoMaps.value=config.featureFlags.demoMaps; places.value=(await api('/places/autocomplete')).items;pickup.value=places.value[0];dropoff.value=places.value[1];demoPosition.value=places.value[0]; } catch(e){quoteError.value=(e as Error).message;} if(isDriver.value) heartbeat=setInterval(()=>{if(!document.hidden)void publishLocation();},10000); });
onUnmounted(()=>{clearInterval(clock);clearInterval(heartbeat);window.removeEventListener('grap:refresh',reload);if(geoWatch!==undefined)navigator.geolocation.clearWatch(geoWatch);});
</script>
<template><div class="page-heading"><div><div class="eyebrow">{{isDriver?'CÙNG GRAP CHUYỂN ĐỘNG':'ĐI MUÔN NƠI, AN TÂM MỖI NGÀY'}}</div><h1>{{isDriver?'Không gian tài xế':'Hôm nay, bạn muốn đi đâu'}}<span class="green-text">{{isDriver?'.':'?'}}</span></h1><p>{{isDriver?'Nhận chuyến, phục vụ khách hàng và theo dõi thu nhập.':'Đặt chuyến xe an toàn, rõ giá trước khi khởi hành.'}}</p></div><Button label="Hỗ trợ" icon="pi pi-headphones" outlined severity="secondary" @click="supportVisible=true"/></div>
<div v-if="demoMaps" class="info-box page-info"><i class="pi pi-code"></i><p>Trải nghiệm local với tuyến đường mẫu. Mở hai trình duyệt hoặc hai cửa sổ độc lập, đăng nhập khách hàng và tài xế để chạy trọn vòng đời. Không dùng cho chuyến thật.</p></div>
<div class="sandbox-grid"><section class="panel booking-panel"><template v-if="isDriver"><div class="availability-toggle"><div><strong>{{availability.data.value?.online?'Đang bật nhận chuyến':'Bạn đang ngoại tuyến'}}</strong><p>{{availability.data.value?.offlineAfterRide?'Sẽ ngoại tuyến sau chuyến hiện tại':'Chỉ nhận chuyến khi GPS & kết nối còn mới'}}</p></div><ToggleSwitch :model-value="availability.data.value?.online??false" :disabled="busy" @update:model-value="toggleOnline" aria-label="Bật nhận chuyến"/></div><QueryState :error="availability.error.value" @retry="availability.refresh"/><template v-if="availability.data.value?.online"><label v-if="demoMaps">Vị trí thử nghiệm (chỉ local)<Select v-model="demoPosition" :options="places" option-label="address" @change="publishLocation"/></label><Button label="Cập nhật vị trí & heartbeat" icon="pi pi-map-marker" severity="secondary" outlined size="small" class="full-width" @click="publishLocation"/><p v-if="geoError" class="form-error">{{geoError}}</p></template><div v-if="offer && !ride" class="offer-card"><div class="ride-active-head"><h3>Hành trình mới dành cho bạn</h3><span>{{offerSeconds}} giây</span></div><p>{{offer.pickup.address}}</p><strong>{{money(offer.driverEntitlement)}}</strong><small class="cell-muted">Quyền lợi dự kiến · Thu khách {{money(offer.customerPayable)}}</small><div class="booking-controls"><Button label="Nhận chuyến" icon="pi pi-check" :disabled="offerSeconds===0" :loading="busy" @click="accept"/><Button label="Bỏ qua" text severity="secondary" :disabled="busy" @click="reject"/></div></div><div v-else-if="!ride" class="query-state"><i class="pi pi-car"></i><strong>{{availability.data.value?.online?'Đang chờ hành trình phù hợp':'Bật nhận chuyến khi bạn sẵn sàng'}}</strong></div></template>
<QueryState :loading="active.loading.value" :error="active.error.value" @retry="active.refresh"/>
<template v-if="ride"><div class="ride-active-head"><span>{{ride.rideCode}}</span><StatusBadge :status="ride.status"/></div><h2>{{serviceNames[ride.serviceTypeCode]}}</h2><div class="booking-route"><div><i class="route-dot pickup"></i>{{ride.pickup.address}}</div><div><i class="route-dot dropoff"></i>{{ride.dropoff.address}}</div></div><div class="quote-price"><div><span>Tiền mặt cần thanh toán</span><strong>{{money(ride.fare.customerPayable)}}</strong></div><small>Giá đã chốt, không tự tăng theo GPS hoặc thời gian chờ.</small></div><div v-if="!isDriver && ride.pickupPin" class="pin-display"><small>MÃ XÁC NHẬN ĐÓN KHÁCH</small><div class="pin-digits">{{ride.pickupPin}}</div><small>Chỉ cung cấp khi bạn đã gặp đúng tài xế.</small></div><div v-if="ride.driver && !isDriver" class="detail-grid"><div><span>Tài xế của bạn</span><strong>{{ride.driver.name}}</strong><small>{{ride.driver.vehicle}}</small></div><div><span>Biển số</span><strong>{{ride.driver.plate}}</strong><small>{{ride.driver.color}}</small></div></div><template v-if="isDriver"><Button v-if="ride.status==='ASSIGNED'" label="Tôi đã đến điểm đón" icon="pi pi-map-marker" class="full-width" :loading="busy" @click="command('arrive')"/><template v-if="ride.status==='DRIVER_ARRIVED'"><label>Nhập mã PIN từ khách hàng<InputText v-model="pin" maxlength="4" inputmode="numeric" placeholder="Mã PIN 4 chữ số"/></label><Button label="Xác nhận & bắt đầu chuyến" icon="pi pi-play" class="full-width" :disabled="!/^\d{4}$/.test(pin)" :loading="busy" @click="command('start')"/></template><Button v-if="ride.status==='IN_PROGRESS'" label="Hoàn tất chuyến" icon="pi pi-check-circle" class="full-width" :loading="busy" @click="command('complete')"/><template v-if="ride.status==='COMPLETED' && ride.payment"><StatusBadge :status="ride.payment.status"/><template v-if="ride.payment.status!=='SUCCEEDED'"><label>Thực tế đã thu (VND)<InputNumber v-model="collected" :min="0" :max="ride.payment.payableAmount-ride.payment.paidAmount"/></label><label>Lý do ghi nhận<InputText v-model="cashReason"/></label><Button label="Xác nhận thu tiền mặt" class="full-width" :loading="busy" @click="collect"/></template></template></template><div class="booking-controls"><Button v-if="!isDriver && ['SEARCHING','ASSIGNED','DRIVER_ARRIVED'].includes(ride.status)" label="Hủy chuyến · miễn phí" severity="danger" outlined @click="action='cancel';reason=''"/><Button v-if="isDriver && ['ASSIGNED','DRIVER_ARRIVED'].includes(ride.status)" label="Yêu cầu rời chuyến" severity="secondary" outlined @click="action='release-assignment';reason=''"/><Button v-if="!isDriver && ['ASSIGNED','DRIVER_ARRIVED','IN_PROGRESS'].includes(ride.status)" label="Chia sẻ chuyến" icon="pi pi-share-alt" severity="secondary" outlined @click="share"/><Button v-if="['ASSIGNED','DRIVER_ARRIVED','IN_PROGRESS'].includes(ride.status)" label="SOS" icon="pi pi-shield" severity="danger" text @click="action='sos'"/><Button v-if="!isDriver && ride.status==='COMPLETED'" label="Đánh giá hành trình" icon="pi pi-star" @click="ratingVisible=true"/></div><p v-if="shareUrl" class="muted journal-key">{{shareUrl}}</p></template>
<template v-else-if="!isDriver"><h2>Đặt hành trình của bạn</h2><p>Giá rõ ràng. Di chuyển thuận tiện.</p><label>Điểm đón<Select v-model="pickup" :options="places" option-label="address" placeholder="Chọn điểm đón" filter/></label><label>Bạn muốn đến đâu?<Select v-model="dropoff" :options="places" option-label="address" placeholder="Chọn điểm đến" filter/></label><div class="service-picker"><button v-for="(label,key) in serviceNames" :key="key" class="service-option" :class="{active:service===key}" @click="service=key"><i class="pi" :class="key==='BIKE'?'pi-directions':'pi-car'"></i><span>{{label}}</span></button></div><p v-if="quoteError" class="form-error">{{quoteError}}</p><Button v-if="!quote" label="Xem giá chuyến đi" icon="pi pi-arrow-right" icon-pos="right" class="full-width" :disabled="!pickup||!dropoff||pickup===dropoff" :loading="busy" @click="getQuote"/><template v-else><div class="quote-price"><div><span>Giá chuyến đi</span><strong>{{money(quote.fare.customerPayable)}}</strong></div><small>{{(quote.estimatedDistanceMeters/1000).toFixed(1)}} km · Khoảng {{Math.ceil(quote.estimatedDurationSeconds/60)}} phút · Tiền mặt</small><p>Báo giá còn hiệu lực {{seconds}} giây</p><small v-if="quote.routeSource==='DEVELOPMENT_FIXTURE'">Tuyến và thời gian là dữ liệu mẫu cho phát triển.</small></div><Button :label="seconds>0?'Xác nhận đặt xe':'Báo giá hết hạn · Lấy giá mới'" icon="pi pi-check" class="full-width" :loading="busy" @click="seconds>0?book():getQuote()"/></template></template>
</section><div><section class="panel sandbox-map-panel"><div class="panel-header"><div><h2>{{ride?'Hành trình của bạn':'Khám phá thành phố'}}</h2><p>TP. Hồ Chí Minh · Vùng phục vụ pilot</p></div><i class="pi pi-map green-text"></i></div><OperationsMap :pickup="mapPickup" :dropoff="mapDropoff" :drivers="ride?.driver?[ride.driver]:[]"/><div class="sandbox-note"><i class="pi pi-info-circle"></i> {{demoMaps?'Đường nối trên bản đồ là minh họa. Giá lấy từ tuyến mẫu phía server.':'Đường nối điểm đón/đến dùng để định hướng. Điều hướng thực hiện trong ứng dụng bản đồ.'}}</div></section><section v-if="isDriver && earnings.data.value" class="panel"><div class="panel-header"><div><h2>Thu nhập của bạn</h2><p>{{earnings.data.value.completedRides}} chuyến hoàn tất</p></div><i class="pi pi-wallet green-text"></i></div><div class="settings-body"><div class="key-row"><span>Quyền lợi tài xế</span><b>{{money(earnings.data.value.entitlement)}}</b></div><div class="key-row"><span>Số dư khả dụng</span><b>{{money(earnings.data.value.balance.available)}}</b></div><div class="key-row"><span>Công nợ phải nộp</span><b>{{money(earnings.data.value.balance.debt)}}</b></div></div></section></div></div>
<section class="panel"><div class="panel-header"><div><h2>Lịch sử hành trình</h2><p>Các chuyến gần nhất của tài khoản hiện tại</p></div><Button icon="pi pi-refresh" text aria-label="Làm mới lịch sử" @click="history.refresh"/></div><QueryState :loading="history.loading.value" :error="history.error.value" @retry="history.refresh"/><RideTable v-if="history.data.value" :rides="history.data.value.items" @select="r=>{ selectedRide=r; collected=r.payment?r.payment.payableAmount-r.payment.paidAmount:0; }"/></section>
<Dialog :visible="!!action" @update:visible="v=>{if(!v)action=''}" modal :header="action==='sos'?'Gửi cảnh báo an toàn':'Xác nhận thay đổi hành trình'" :style="{width:'460px'}"><template v-if="action==='sos'"><p class="muted">Cảnh báo được gửi cho đội hỗ trợ nội bộ khi có mạng. Hệ thống chưa cung cấp cam kết điều động lực lượng khẩn cấp.</p><p class="muted">Sau khi gửi, chờ thông báo xác nhận tiếp nhận; nếu mất mạng, cảnh báo chưa được gửi.</p></template><label v-else>Lý do<Textarea v-model="reason" rows="3" class="full-width"/></label><template #footer><Button label="Quay lại" text severity="secondary" @click="action=''"/><Button :label="action==='sos'?'Gửi cảnh báo':'Xác nhận'" :severity="action==='sos'?'danger':undefined" :disabled="action!=='sos'&&reason.trim().length<3" :loading="busy" @click="action==='sos'?run(async()=>{await sos();action=''}):command(action)"/></template></Dialog><Dialog v-model:visible="supportVisible" modal header="Bạn cần hỗ trợ điều gì?" :style="{width:'480px'}"><label>Nội dung cần hỗ trợ<Textarea v-model="supportBody" class="full-width" rows="5"/></label><template #footer><Button label="Gửi yêu cầu" icon="pi pi-send" :disabled="supportBody.trim().length<5" :loading="busy" @click="support"/></template></Dialog><Dialog v-model:visible="ratingVisible" modal header="Hành trình của bạn thế nào?" :style="{width:'440px'}"><div class="rating-input"><button v-for="n in 5" :key="n" :class="{active:n<=stars}" :aria-label="n+' sao'" @click="stars=n"><i class="pi pi-star-fill"></i></button></div><label>Chia sẻ thêm về trải nghiệm<Textarea v-model="comment" rows="3" class="full-width"/></label><template #footer><Button label="Gửi đánh giá" :loading="busy" @click="rate"/></template></Dialog>
</template>
